import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            B = []
            for _ in range(N):
                B.append(int(next(iterator)))
        except StopIteration:
            break

        A = [0] * N
        current_mex = 0
        present = set()

        possible = True

        for i in range(N):
            b_val = B[i]

            if b_val == -1:
                if current_mex > 0:
                    A[i] = current_mex - 1
                    present.add(A[i])
                else:
                    A[i] = 0
                    present.add(0)
                    current_mex = 1
            else:
                if b_val < current_mex:
                    possible = False
                    break

                if b_val > current_mex:
                    needed = b_val - current_mex
                    for k in range(needed):
                        val = current_mex + k
                        while val in present:
                            val += 1
                        present.add(val)
                        A[i] = val
                        current_mex += 1

                    if current_mex != b_val:
                        possible = False
                        break
                else:
                    A[i] = b_val
                    present.add(b_val)
                    current_mex = b_val + 1
                    while current_mex in present:
                        current_mex += 1

        if not possible:
            out_lines.append("-1")
        else:
            out_lines.append(" ".join(map(str, A)))

    sys.stdout.write("\n".join(out_lines) + "\n")

if __name__ == "__main__":
    solve()
